type User = { name: string };

function isUser(value: unknown): value is User {
  return typeof value === 'object'
    && value !== null
    && 'name' in value
    && typeof value.name === 'string';
}

const input: unknown = { name: 'Ada' };
if (isUser(input)) {
  console.log(input.name);
}

