import type { ChangeEvent, MouseEvent, SubmitEvent } from 'react';

export function handleChange(event: ChangeEvent<HTMLInputElement>) {
  console.log(event.currentTarget.value);
}

export function handleClick(event: MouseEvent<HTMLButtonElement>) {
  console.log(event.currentTarget.name);
}

export function handleSubmit(event: SubmitEvent<HTMLFormElement>) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  console.log(data.get('name'));
}
